import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第八十二章 感受的产生如同摩擦生火","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/82第八十二章 感受的产生如同摩擦生火.md","filePath":"meditation/巴利文大藏经/82第八十二章 感受的产生如同摩擦生火.md"}'),o={name:"meditation/巴利文大藏经/82第八十二章 感受的产生如同摩擦生火.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第八十二章-感受的产生如同摩擦生火" tabindex="-1">第八十二章 感受的产生如同摩擦生火 <a class="header-anchor" href="#第八十二章-感受的产生如同摩擦生火" aria-label="Permalink to &quot;第八十二章 感受的产生如同摩擦生火&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部12相应62经/未听闻经第二(因缘相应/因缘篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园。有一天，佛陀对出家弟子们说：“弟子们，如来现在来为你们说法，你们要认真的听，你们要仔细的思考。”</p><p>出家弟子们回答：“世尊，我们会认真听您说法的，我们会仔细的思考的，恭请世尊您为我们说法。”</p><p>佛陀说：“弟子们，世间还没有受到如来教导的人，他们有可能不会挂念和执着四大元素（四大元素解释，见第八十一章）构成的事物，他们有可能会从四大元素构成的事物中解脱出来，为什么呢？因为这些由四大元素构成的事物看的见，摸得着，能被世间人获得、拥有。这些事物也会衰败、消失，拥有它们的人也会失去它们。这些由四大元素构成的身体会成长、生病、衰老、死亡。世间人获得、失去世间的事物，或者无法获得世间的事物，或者看着自己获得的事物慢慢的衰败，他们就会明白世间一切的事物都是随时在变化的，都是无法永恒保持不变的，都是无法永远存在的，由此就能从对这些事物的沉迷中清醒过来，不会再被这些事物迷惑，不会再挂念和执着这些事物，从对这些事物的沉迷中解脱出来。同样的道理，世间人感受自己或者看到别人的身体成长、生病、衰老、死亡就会明白自己和别人的身体是无法青春永驻的，是无法长生不死的，自己和别人的身体是随时都在变化的，是无法永恒保持不变的，是无法永远在世间存在的，就会从对自己和别人身体的沉迷中清醒过来，就不会再被自己或是别人的身体所迷惑，不会再挂念和执着自己或是别人的身体，就能从对自己或是别人身体的沉迷中解脱出来。</p><p>弟子们，然而没有受到如来教导的人，他们却很难从自己的心境、念想、分别中解脱出来，为什么呢？因为长久以来，他们内心会有这样的想法：「这个是我的，这个是我拥有的，我就是这个，这个就是永远不变的真我」。这些就是世间人执着不舍的心境、念想、分别。他们很难从这些心境、念想、分别中解脱出来。</p><p>世间人对于四大元素构成的身体执着和挂念还可以被理解，毕竟世间人的身体可以在世间存在一年、二年、三年、四年、五年、十年、二十年、三十年、四十年、五十年、一百年，或者更久，这些都是他们看得见，摸得着的，并且他们的身体每年不会有多大变化，是慢慢在变化的，而且他们周围的人也是在慢慢变化的，让他们在短时间内无法察觉到自己身体和别人身体的微妙变化。然而，弟子们，世间人对心境、念想、分别的执着和挂念更加的难以解脱，世间人被心境、念想、分别束缚捆绑的更加严实牢固，因为世间人的心境、念想、分别是随时都在变化的，是随时都在改变的。这个心境、念想、分别生起了，那个心境、念想、分别就灭尽了；那个心境、念想、分别生起了，这个心境、念想、分别就灭尽了；生生灭灭、循环往复、无有穷尽，世间人的心境、念想、分别，随着他们遇见的事物事情时时刻刻都在不停的改变。</p><p>弟子们，已经受到如来教导的圣弟子们，应该这样去观想：「当这个生起、存在了，则那个也会生起、存在；以这个的生起、存在为前提条件，就会有那个的生起、存在；当这个不存在了，则那个也会消失不见；以这个的灭尽、消失为前提条件，那个也会灭尽、消失。」弟子们，这就是缘起法（缘起法解释，见第四十八章、第四十九章）。</p><p>弟子们，当能够感觉快乐的「触」生起来的时候，就会产生出快乐的感受。当感觉快乐的「触」灭尽、消失的时候，那么由这个「触」产生出来的快乐感受就会被灭尽、除灭。</p><p>弟子们，当能够感觉痛苦的「触」生起来的时候，就会产生出痛苦的感受。当感觉痛苦的「触」灭尽、消失的时候，那么由这个「触」产生出来的痛苦感受就会被灭尽、除灭。</p><p>弟子们，当能够感觉不苦不乐的「触」生起来的时候，就会产生出不苦不乐的感受。当感觉不苦不乐的「触」灭尽、消失的时候，那么由这个「触」产生出来的不苦不乐感受就会被灭尽、除灭。</p><p>弟子们，这就如同两个木柴互相接触，持续不断的摩擦，时间长了，这两根木柴就会发热生火，如果在这两根摩擦的木柴还没有生出火之前，就将它们分开、分离，那么这两根木柴之前摩擦产生出来的热度就会慢慢的降下来，最后与外界的温度保持一致，这样它们摩擦时产生出来的热量就被除灭了，就被平息了。同样的道理，弟子们，当能够感觉快乐的「触」生起来的时候，就会产生出快乐的感受。当感觉快乐的「触」灭尽、消失的时候，那么由这个「触」产生出来的快乐感受就会被灭尽、除灭。当能够感觉痛苦的「触」生起来的时候，就会产生出痛苦的感受。当感觉痛苦的「触」灭尽、消失的时候，那么由这个「触」产生出来的痛苦感受就会被灭尽、除灭。当能够感觉不苦不乐的「触」生起来的时候，就会产生出不苦不乐的感受。当感觉不苦不乐的「触」灭尽、消失的时候，那么由这个「触」产生出来的不苦不乐感受就会被灭尽、除灭。</p><p>这些快乐感受的产生、灭尽，痛苦感受的产生、灭尽，不苦不乐感受的产生、灭尽，就如同两个木柴互相接触，持续不断的摩擦，时间长了，这两根木柴就会发热生火，如果在这两根摩擦的木柴还没有生出火之前，就将它们分开、分离，那么它们产生出来的热量就会慢慢的消失，最后与外界的温度保持一致，它们摩擦产生的热量就被灭除、平息了一样。当能够感觉快乐、痛苦、不苦不乐的「触」生起来的时候，就会产生出快乐、痛苦、不苦不乐的感受。当感觉快乐、痛苦、不苦不乐的「触」灭尽、消失的时候，那么由这个「触」产生出来的快乐、痛苦、不苦不乐的感受就会被灭尽、除灭。</p><p>弟子们，当你们这样去观想的时候，就不会挂念和执着一切的「触」，就不会挂念和执着一切的感受，就不会挂念和执着一切的念想。就不会挂念和执着一切的行为，就不会挂念和执着一切的认识、分别、判断。没有执着和挂念，你们就不会被任何的「触」、事物、感受、念想、行为、认识、分别、判断束缚捆绑，这样没有执着和挂念，你们就从世间的烦恼和痛苦中解脱了出来。当你们解脱的时候，就会证悟解脱的智慧和果位，你们就会明白：「从这一世开始，我已经不会出生在世间，我行为、言语、念想的修行已经圆满，我应该做的事情已经做好，我不会再有生死轮回的状态，我不会再出生在这个世间，我已经永远从生死轮回中解脱出来」。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',16)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
